			"Значения": [
				"1 - дошкольное образование",
				"2 - начальное общее образование",
				"3 - основное общее образование",
				"4 - среднее общее образование",
				"5 - среднее профессиональное образование",
				"6 - высшее образование",
				"неизвестно"
			],
			"ВозможностьРедактирования": false
		}
	}
}

{
	"СпискиВыбора": {
